    def build_cal(month, year, start, total, highlight, inf_day=None):
        days = ["L","M","M","J","V","S","D"]
        inf_svg = '<svg width="16" height="9" viewBox="0 0 18 10" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M9 5C9 5 6.5 1.5 4.5 1.5C2.5 1.5 1 3 1 5C1 7 2.5 8.5 4.5 8.5C6.5 8.5 9 5 9 5ZM9 5C9 5 11.5 8.5 13.5 8.5C15.5 8.5 17 7 17 5C17 3 15.5 1.5 13.5 1.5C11.5 1.5 9 5 9 5Z" stroke="rgba(210,130,130,0.9)" stroke-width="1.4" fill="none" stroke-dasharray="1000" stroke-dashoffset="1000" style="animation:infinityDraw 2s 0.5s ease forwards;"/></svg>'
        h = '<div class="cal-outer"><div class="cal-header"><div class="cal-month">' + month + '</div><div class="cal-year">' + str(year) + '</div></div><div class="cal-grid">'
        for d in days: h += '<div class="cal-day-name">' + d + '</div>'
        for _ in range(start): h += '<div class="cal-cell empty"></div>'
        for day in range(1, total+1):
            cls = "cal-cell"
            content = str(day)
            if day == highlight: cls += " highlighted"
            elif inf_day and day == inf_day:
                cls += " infinity-cell"
                content = str(day) + inf_svg
            h += '<div class="' + cls + '">' + content + '</div>'
        h += '</div></div>'
        return h

    apr = build_cal("Abril", 2026, 1, 30, 20)
    may = build_cal("Mayo", 2026, 3, 31, 22)
    may_inf = build_cal("Mayo", 2026, 3, 31, 22, inf_day=22)

    p = '<div class="particles">'
